<?php
declare(strict_types=1);
/** Centro de conciliación integral · V1 · consultas GET exclusivamente. */
require_once __DIR__.'/../app/helpers/auth.php';
require_once __DIR__.'/../app/config/database.php';
require_once __DIR__.'/../app/helpers/erp_conciliacion_integral.php';
requireLogin();
header('Cache-Control: private, no-store, max-age=0');
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);header('Allow: GET');exit('Consulta de solo lectura.');}
$u=currentUser()?:[];$rol=strtoupper(trim((string)($u['rol_original']??$u['rol']??'')));
if((int)($u['id']??0)<1||!in_array($rol,['ADMINISTRADOR','ADMIN','DIRECCION','COMPRAS'],true)){
    http_response_code(403);exit('Acceso limitado a Compras y Administración.');
}
$id=filter_input(INPUT_GET,'oc',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$q=mb_substr(trim((string)($_GET['q']??'')),0,70);
$destino=trim((string)($_GET['destino']??''));
$permitidos=['','TAPACHULA','TOSCANA','HIDALGO_FARMACIA','HIDALGO_BODEGA','TUXTLA_FARMACIA','TUXTLA_BODEGA'];
if(!in_array($destino,$permitidos,true))$destino='';
$ocEstado=trim((string)($_GET['oc_estado']??''));
if(!in_array($ocEstado,['','BORRADOR','EMITIDA','PARCIAL','COMPLETA','CANCELADA'],true))$ocEstado='';
$estado=trim((string)($_GET['estado']??''));
if(!in_array($estado,['','REVISAR','PENDIENTE','SIN EVIDENCIA','SIN AUDITORÍA','CONCILIADO','NO EMITIDA','SIN PARTIDAS'],true))$estado='';
$exp=($_GET['exportar']??'')==='csv';$page=max(1,min(200,(int)($_GET['pagina']??1)));
$rows=[];$detalle=null;$error='';$sinOC=[];$resumen=[];$total=0;
try{
    $db=(new Database())->connect();
    $estructura=ci_estructura($db);
    if($estructura['faltan'])throw new RuntimeException('Faltan tablas del flujo de Compras: '.implode(', ',$estructura['faltan']).'. No se calcularon saldos.');
    if($id){
        $detalle=ci_detalle($db,$id);
        if(!$detalle){http_response_code(404);exit('Orden de compra no encontrada.');}
    } else {
        $rows=ci_listado($db,$q,$destino,$ocEstado,$estado);$total=count($rows);
        foreach($rows as $r){$k=$r['estado'];$resumen[$k]=($resumen[$k]??0)+1;}
        $sinOC=ci_select($db,'SELECT f.id,f.folio_interno,f.numero_factura,f.fecha_factura,f.sucursal,f.estado,p.nombre proveedor FROM erp_facturas f LEFT JOIN proveedores p ON p.id=f.proveedor_id WHERE f.orden_id IS NULL ORDER BY f.id DESC LIMIT 25');
    }
} catch(Throwable $ex){error_log('Conciliación integral G&D: '.$ex->getMessage());$error=$ex instanceof RuntimeException?$ex->getMessage():'No se pudo consultar la conciliación. Comprueba el esquema de la base de pruebas.';}
$csvFields=['OC','Proveedor','Destino','Estado OC','Estado conciliación','Solicitadas','Recibidas registradas','Facturadas','Aceptadas netas','Aplicadas netas','Por recibir','Por facturar','Por verificar','Por aplicar'];
if($exp && !$error){
    header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="conciliacion_integral_gyd.csv"');
    $out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$csvFields);
    $exportRows=$detalle?[$detalle]:$rows;
    foreach($exportRows as $r){
      $o=$r['orden'];$t=$r['totales'];
      fputcsv($out,[ci_csv_seguro((string)$o['folio']),ci_csv_seguro((string)$o['proveedor']),ci_csv_seguro((string)$o['destino']),
        (string)$o['estado'],$r['estado'],$t['solicitado'],$r['tiene_recepciones']?$t['recibido']:'Sin recepción documental',
        $t['facturado'],$t['aceptado'],$t['aplicado'],$r['tiene_recepciones']?$t['por_recibir']:'No determinable',
        $t['por_facturar'],$t['por_verificar'],$t['por_aplicar']]);
    }
    fclose($out);exit;
}
$destinos=['TAPACHULA'=>'Tapachula – Farmacia','TOSCANA'=>'Toscana – Farmacia','HIDALGO_FARMACIA'=>'Hidalgo – Farmacia','HIDALGO_BODEGA'=>'Hidalgo – Bodega','TUXTLA_FARMACIA'=>'Tuxtla – Farmacia','TUXTLA_BODEGA'=>'Tuxtla – Bodega'];
function ci_estado_clase(string $x):string {return $x==='REVISAR'?'bad':($x==='CONCILIADO'?'ok':($x==='PENDIENTE'?'warn':'neutral'));}
