<section class="panel"><div class="toolbar"><div><h2><?=ci_html($o['folio'])?> · <?=ci_html($o['proveedor'])?></h2><span class="muted"><?=ci_html($destinos[$o['destino']]??$o['destino'])?> · <?=ci_html($o['fecha'])?> · Estado OC: <?=ci_html($o['estado'])?></span></div><span class="tag <?=ci_estado_clase($detalle['estado'])?>"><?=ci_html($detalle['estado'])?></span></div>
<div class="grid">
<?php foreach(['Solicitadas'=>'solicitado','Recibidas registradas'=>'recibido','Facturadas'=>'facturado','Aceptadas netas'=>'aceptado','Aplicadas netas'=>'aplicado','Por recibir'=>'por_recibir','Por facturar'=>'por_facturar','Por aplicar'=>'por_aplicar'] as $et=>$k):?><div class="kpi"><small><?=ci_html($et)?></small><strong><?php if(!$detalle['tiene_recepciones']&&in_array($k,['recibido','por_recibir'],true)):?>—<?php else:?><?=number_format($t[$k])?><?php endif;?></strong></div><?php endforeach;?></div>
