<div class="cards no-print"><a class="btn alt" href="erp_conciliacion_integral.php">← Volver al resumen</a><a class="btn" href="?oc=<?=(int)$o['id']?>&amp;exportar=csv">Exportar CSV</a><button type="button" class="btn alt" onclick="window.print()">Imprimir / Guardar PDF</button><a class="btn alt" href="erp_oc_win.php?ver=<?=(int)$o['id']?>">Ver orden</a></div></section>
