<?php foreach($detalle['partidas'] as $r):?><tr><td><b><?=ci_html($r['descripcion'])?></b><div class="muted"><?=ci_html($r['codigo'])?></div></td><td class="num"><?=$r['solicitado']?></td><td class="num"><?=$detalle['tiene_recepciones']?$r['recibido']:'—'?></td><td class="num"><?=$r['facturado']?></td><td class="num"><?=$r['aceptado']?></td><td class="num"><?=$r['aplicado']?></td><td class="num"><?=$r['por_facturar']?></td><td class="num"><?=$r['por_verificar']?></td><td class="num"><?=$r['por_aplicar']?></td><td><span class="tag <?=ci_estado_clase($r['estado'])?>"><?=ci_html($r['estado'])?></span><?php if($r['observaciones']):?><div class="red small"><?=ci_html(implode('; ',$r['observaciones']))?></div><?php endif;?></td></tr><?php endforeach; ?></tbody></table></div></section>
