<?php elseif(!$error): ?>
<section class="panel"><h2>Filtrar órdenes y conciliación</h2><form method="get" class="form"><label>Orden / proveedor<input name="q" value="<?=ci_html($q)?>" placeholder="OC-0000010 / proveedor"></label><label>Destino<select name="destino"><option value="">Todos</option><?php foreach($destinos as $key=>$text):?><option value="<?=ci_html($key)?>" <?=$key===$destino?'selected':''?>><?=ci_html($text)?></option><?php endforeach;?></select></label><label>Estado OC<select name="oc_estado"><option value="">Todos</option><?php foreach(['BORRADOR','EMITIDA','PARCIAL','COMPLETA','CANCELADA'] as $value):?><option <?=$ocEstado===$value?'selected':''?>><?=$value?></option><?php endforeach;?></select></label><label>Conciliación<select name="estado"><option value="">Todos</option><?php foreach(['REVISAR','PENDIENTE','SIN EVIDENCIA','SIN AUDITORÍA','CONCILIADO','NO EMITIDA','SIN PARTIDAS'] as $value):?><option <?=$estado===$value?'selected':''?>><?=ci_html($value)?></option><?php endforeach;?></select></label><button>Filtrar</button><a class="btn alt" href="erp_conciliacion_integral.php">Limpiar</a></form></section>
