<div class="grid"><?php foreach(['REVISAR'=>'Con diferencias','PENDIENTE'=>'Con pendientes','SIN EVIDENCIA'=>'Sin recepción documental','CONCILIADO'=>'Sin diferencias detectadas'] as $k=>$label):?><div class="kpi"><small><?=ci_html($label)?></small><strong><?=number_format($resumen[$k]??0)?></strong></div><?php endforeach;?></div>
<div class="toolbar no-print"><span class="muted">Se visualizan 40 órdenes por página. El CSV exporta todo el conjunto filtrado, hasta 500 órdenes.</span><div><a class="btn" href="?<?=ci_html(http_build_query(['q'=>$q,'destino'=>$destino,'oc_estado'=>$ocEstado,'estado'=>$estado,'exportar'=>'csv']))?>">Exportar CSV</a> <button class="btn alt" onclick="window.print()" type="button">Imprimir / PDF</button></div></div>
